```javascript
const { Client, GatewayIntentBits } = require('discord.js');

// Création d'un nouveau client Discord.js
const client = new Client({
  intents: [
    GatewayIntentBits.Guilds,
    GatewayIntentBits.GuildMessages,
    GatewayIntentBits.MessageContent,
  ],
});

// Connexion du client au serveur Discord
client.on('ready', () => {
  console.log(`Bot en ligne : ${client.user.tag}`);
});

// Commande "bannir"
client.on('interactionCreate', async interaction => {
  if (!interaction.isChatInputCommand()) return;

  if (interaction.commandName === 'bannir') {
    // Vérification des permissions
    if (!interaction.memberPermissions?.has('BAN_MEMBERS')) {
      return interaction.reply({ content: 'Vous n\'avez pas la permission de bannir les utilisateurs.', ephemeral: true });
    }

    // Récupération de l'utilisateur à bannir
    const user = interaction.options.getUser('utilisateur');

    try {
      // Bannissement de l'utilisateur
      await interaction.guild.members.ban(user.id);

      // Réponse de confirmation
      return interaction.reply({ content: `L'utilisateur ${user.tag} a été banni.` });
    } catch (error) {
      console.error(error);
      return interaction.reply({ content: 'Une erreur est survenue lors du bannissement de l\'utilisateur.', ephemeral: true });
    }
  }
});

// Connexion du client au serveur Discord
client.login(process.env.TOKEN);
```

